export type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };

export type QuoteStep = { op: 'quote'; items: Item[] };

export type Step = QuoteStep;

export type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };

export type Result = { premium: number };

export function runScenario(scenario: Scenario): { results: Result[] } {
  return { results: scenario.steps.map((step) => ({ premium: quote(step.items) })) };
}

const BASE_PREMIUMS: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40 };

function quote(items: Item[]): number {
  const mainItems = items.filter((item) => item.type !== 'rune');
  const runeCount = items.length - mainItems.length;
  const base = mainItems.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0) + componentsBasePremium(runeCount);
  return Math.ceil(base + base * 0.1 + 5);
}

function componentsBasePremium(count: number): number {
  return count === 3 ? 60 : count * 25;
}

