content.content:
import { Customer, Item } from './types';

const BASE_PREMIUMS: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40 };
const FIRST_INSURANCE_SURCHARGE = 0.1;
const PROCESSING_FEE = 5;

const CURSE_SURCHARGE = 0.5;
const HIGH_ENCHANTMENT_SURCHARGE = 0.3;

const LOYALTY_DISCOUNT = 0.2;
const LOYALTY_YEARS = 2;
const FOLLOW_UP_DISCOUNT = 0.15;

export function quote(items: Item[], customer: Customer, isFollowUpContract: boolean): number {
  const base = policyBasePremium(items);
  const itemSurcharges = items.reduce((sum, item) => sum + itemSurcharge(item), 0);
  return Math.ceil(base + itemSurcharges + base * policyModifierRate(customer, isFollowUpContract) + PROCESSING_FEE);
}

function policyModifierRate(customer: Customer, isFollowUpContract: boolean): number {
  const loyalty = customer.yearsWithMHPCO >= LOYALTY_YEARS ? LOYALTY_DISCOUNT : 0;
  const followUp = isFollowUpContract ? FOLLOW_UP_DISCOUNT : 0;
  return FIRST_INSURANCE_SURCHARGE - loyalty - followUp;
}

const COMPONENT_TYPES = ['rune', 'moonstone'];
const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function policyBasePremium(items: Item[]): number {
  const unknown = items.find((item) => !(item.type in BASE_PREMIUMS) && !COMPONENT_TYPES.includes(item.type));
  if (unknown) throw new Error(`Unknown item type: ${unknown.type}`);
  const mainItems = items.filter((item) => !COMPONENT_TYPES.includes(item.type));
  const mainItemsPremium = mainItems.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const componentsPremium = COMPONENT_TYPES.reduce(
    (sum, type) => sum + componentsBasePremium(items.filter((item) => item.type === type).length),
    0,
  );
  return mainItemsPremium + componentsPremium;
}

function componentsBasePremium(count: number): number {
  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
}

const HIGH_ENCHANTMENT_LEVEL = 5;

function itemSurcharge(item: Item): number {
  const curse = item.cursed ? CURSE_SURCHARGE : 0;
  const enchantment = (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_SURCHARGE : 0;
  return (BASE_PREMIUMS[item.type] ?? 0) * (curse + enchantment);
}

