import { ClaimResult, Damage, Item } from './types';
import { catalogEntry } from './catalog';

const DEDUCTIBLE = 100;
const HIGH_ENCHANTMENT_LEVEL = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT = 0.5;

export class Policy {
  private remainingCap: number;

  constructor(private readonly items: Item[]) {
    this.remainingCap = 2 * items.reduce((sum, item) => sum + (catalogEntry(item.type)?.insuranceValue ?? 0), 0);
  }

  claim(damages: Damage[]): ClaimResult {
    const undamagedItems = [...this.items];
    const desired = damages.reduce((sum, damage) => {
      const item = undamagedItems.splice(undamagedItems.findIndex((insured) => insured.type === damage.itemType), 1)[0];
      return sum + Math.max(0, reimbursement(item, damage.amount) - DEDUCTIBLE);
    }, 0);
    const payout = Math.min(desired, this.remainingCap);
    this.remainingCap -= payout;
    return { payout, remainingCap: this.remainingCap };
  }
}

function reimbursement(item: Item, amount: number): number {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? amount * HIGH_ENCHANTMENT_REIMBURSEMENT : amount;
}
EOF
