  const loyalty = customer.yearsWithMHPCO >= LOYALTY_YEARS ? LOYALTY_DISCOUNT : 0;
  const followUp = isFollowUpContract ? FOLLOW_UP_DISCOUNT : 0;
  return FIRST_INSURANCE_SURCHARGE - loyalty - followUp;
}
